# shellcheck shell=bash
# niri window decorations (dark): amber focus ring at 80% alpha.
# Output: ports/niri/terminal-noir.kdl

build_niri() {
    jq -r '
        .variants.dark as $c
        | ($c.accent.primary | ascii_downcase) as $amber
        | ($c.surface.outline | ascii_downcase) as $outline
        | ($c.accent.error | ascii_downcase) as $urgent
        | "// Terminal Noir for niri. https://terminalnoir.web.app",
          "// Generated by scripts/build from palette/palette.json.",
          "// Include it from config.kdl, or copy the blocks into your layout {}.",
          "layout {",
          "    focus-ring {",
          "        width 3",
          "        active-color \"\($amber)cc\"",
          "        inactive-color \"\($outline)\"",
          "        urgent-color \"\($urgent)\"",
          "    }",
          "",
          "    border {",
          "        off",
          "        width 3",
          "        active-color \"\($amber)cc\"",
          "        inactive-color \"\($outline)\"",
          "        urgent-color \"\($urgent)\"",
          "    }",
          "",
          "    insert-hint {",
          "        color \"\($amber)80\"",
          "    }",
          "}"
    ' "$PALETTE" > "$OUT/ports/niri/terminal-noir.kdl"
}
